//! TEXTAREA wrap reflection and actual native form submission wrapping.
use super::*;
fn fixture()->(Document,Forms,Page){fixture_method("post")}
fn fixture_method(method:&str)->(Document,Forms,Page){let mut d=crate::html::parse(&format!("<html><body><form id=form method={method} action='/submit'><textarea id=area name=q cols=3 wrap=hard>abcdefg</textarea><input id=neighbor value=seed></form></body></html>"));d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://textarea-wrap.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn body(d:&Document,f:&Forms)->String{let owner=(0..d.nodes.len()).find(|n|d.attr(*n,"id")==Some("form")).unwrap();let l=crate::navigation::address("https://textarea-wrap.test/source",&crate::navigation::Location::home()).unwrap();let result=f.submit_request(d,owner,None,&l,&l).unwrap();let crate::http::Request::FormPost{body,..}=result.request else{panic!("POST")};String::from_utf8(body).unwrap()}
#[test]
fn textarea_wrap_canonical_descriptor_exact_dom_string_and_once_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),a=Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'wrap');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get wrap'||a.set.name!=='set wrap'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'wrap')||x.wrap!=='hard')throw 'canonical wrap';var calls=0;x.wrap={toString:function(){calls++;return 'HARD';},valueOf:function(){throw 'wrong hint';}};if(calls!==1||x.wrap!=='HARD'||x.getAttributeNS(null,'wrap')!=='HARD'||x.value!=='abcdefg'||x.defaultValue!=='abcdefg')throw 'exact wrap metadata';");}
#[test]
fn textarea_wrap_missing_and_invalid_reflect_authored_content(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.removeAttribute('wrap');if(x.wrap!=='')throw 'missing wrap reflection';x.wrap='unknown';if(x.wrap!=='unknown'||x.getAttribute('wrap')!=='unknown'||x.value!=='abcdefg')throw 'invalid metadata reflection';x.wrap=null;if(x.wrap!=='null')throw 'ordinary DOMString null';");}
#[test]
fn textarea_wrap_hard_initial_native_submission_adds_crlf_without_changing_api_value(){let(d,f,_)=fixture();assert_eq!(body(&d,&f),"q=abc%0D%0Adef%0D%0Ag");let c=f.controls.values().find(|c|c.kind==forms::Kind::TextArea).unwrap();assert_eq!(c.value.text(),"abcdefg");assert!(!c.dirty_value);}

#[test]
fn textarea_wrap_width_and_mode_matrix_uses_html_prefixes_without_large_width_overflow(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');");for(columns,expected)in[("1","q=a%0D%0Ab%0D%0Ac%0D%0Ad%0D%0Ae%0D%0Af%0D%0Ag"),(" +2tail","q=ab%0D%0Acd%0D%0Aef%0D%0Ag"),("3.9","q=abc%0D%0Adef%0D%0Ag"),("0","q=abcdefg"),("-0","q=abcdefg"),("-1","q=abcdefg"),("","q=abcdefg"),("\u{a0}2","q=abcdefg"),("2147483648","q=abcdefg"),("999999999999999999999999999999999999999999999999999999999999999","q=abcdefg")]{p.begin_job();run(&mut d,&mut f,&mut p,&format!("x.setAttribute('cols','{columns}');"));assert_eq!(body(&d,&f),expected,"cols {columns:?}");}run(&mut d,&mut f,&mut p,"x.cols=3;");for mode in ["hard","HARD","HaRd","soft","off","hard "," hard","","unknown"]{p.begin_job();run(&mut d,&mut f,&mut p,&format!("x.wrap='{mode}';if(x.wrap!=='{mode}')throw 'exact authored wrap';"));assert_eq!(body(&d,&f),if mode.eq_ignore_ascii_case("hard"){"q=abc%0D%0Adef%0D%0Ag"}else{"q=abcdefg"},"mode {mode:?}");}run(&mut d,&mut f,&mut p,&format!("x.wrap='hard';x.cols=201;x.value='{}';","a".repeat(202)));assert_eq!(body(&d,&f),format!("q={}%0D%0Aa","a".repeat(201)));}
#[test]
fn textarea_wrap_unicode_scalar_columns_and_existing_crlf_have_no_extra_trailing_break(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.cols=2;x.value='A😀B\\r\\nCDE';if(x.value!=='A😀B\\nCDE'||x.textLength!==8)throw 'normalized API value';");assert_eq!(body(&d,&f),"q=A%F0%9F%98%80%0D%0AB%0D%0ACD%0D%0AE");run(&mut d,&mut f,&mut p,"x.value='AB\\nCD\\n';");assert_eq!(body(&d,&f),"q=AB%0D%0ACD%0D%0A");run(&mut d,&mut f,&mut p,"x.value='\\n\\n';");assert_eq!(body(&d,&f),"q=%0D%0A%0D%0A");run(&mut d,&mut f,&mut p,"x.value='';");assert_eq!(body(&d,&f),"q=");}
#[test]
fn textarea_wrap_get_and_post_share_exact_native_submission_transform(){let(post_d,post_f,_)=fixture();let expected=body(&post_d,&post_f);let(d,f,_)=fixture_method("get");let owner=(0..d.nodes.len()).find(|n|d.attr(*n,"id")==Some("form")).unwrap();let l=crate::navigation::address("https://textarea-wrap.test/source",&crate::navigation::Location::home()).unwrap();for script in [false,true]{let submitted=if script{f.script_submit_request(&d,owner,&l,&l)}else{f.submit_request(&d,owner,None,&l,&l)}.unwrap();assert_eq!(submitted.location.url.unwrap().query.as_deref(),Some(expected.as_str()));}}
#[test]
fn textarea_wrap_attribute_producers_observe_real_state_without_editor_rebuild(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.value='abcdefg';var attribute=x.getAttributeNodeNS(null,'wrap'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true,attributeFilter:['wrap']});");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for source in ["x.setAttribute('wrap','soft');","x.setAttributeNS(null,'wrap','soft');","attribute.value='soft';","attribute.nodeValue='soft';","attribute.textContent='soft';"]{p.begin_job();run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.wrap!=='soft'||x.getAttributeNodeNS(null,'wrap')!==attribute||records.length!==1||records[0].attributeName!=='wrap'||records[0].target!==x||x.value!=='abcdefg'||x.defaultValue!=='abcdefg')throw 'real wrap mutation';");assert_eq!(body(&d,&f),"q=abcdefg");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(3,1,2,true));}run(&mut d,&mut f,&mut p,"var replacement=document.createAttribute('wrap');replacement.value='hard';x.setAttributeNodeNS(replacement);if(x.wrap!=='hard'||attribute.ownerElement!==null||replacement.ownerElement!==x)throw 'wrap Attr replacement';");assert_eq!(body(&d,&f),"q=abc%0D%0Adef%0D%0Ag");}
#[test]
fn textarea_wrap_brands_saved_authority_reentrant_and_abrupt_dom_string_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),P=HTMLTextAreaElement.prototype,a=Object.getOwnPropertyDescriptor(P,'wrap'),calls=0;for(var bad of [{},document,document.getElementById('neighbor'),Object.create(P)]){try{a.set.call(bad,{toString:function(){calls++;return 'soft';}});throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls||x.wrap!=='hard')throw 'bad brand converted';x.wrap={toString:function(){calls++;x.wrap='soft';return 'HARD';}};if(calls!==1||x.wrap!=='HARD')throw 'outer string conversion';var marker={};try{x.wrap={toString:function(){x.setAttribute('data-side','kept');throw marker;}};throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(x.wrap!=='HARD'||x.getAttribute('data-side')!=='kept')throw 'abrupt state';Object.defineProperty(P,'wrap',{get:function(){return 'author';},set:function(v){this.setAttribute('data-author',v);},configurable:true});x.wrap='override';a.set.call(x,'soft');if(x.wrap!=='author'||a.get.call(x)!=='soft'||x.getAttribute('data-author')!=='override')throw 'saved wrap authority';delete P.wrap;if(x.wrap!==undefined)throw 'deleted hidden member';Object.defineProperty(P,'wrap',a);var C=HTMLTextAreaElement;delete window.HTMLTextAreaElement;if(!(x instanceof C)||a.get.call(x)!=='soft')throw 'saved roots';");assert_eq!(body(&d,&f),"q=abcdefg");}
#[test]
fn textarea_wrap_native_inert_exact_namespace_raw_strings_and_independent_copies(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),owner=new Document(),inert=owner.createElementNS('http://www.w3.org/1999/xhtml','textarea');for(var target of [x,inert]){target.removeAttribute('wrap');target.setAttributeNS('urn:other','wrap','hard');target.setAttributeNS(null,'WRAP','hard');if(target.wrap!=='')throw 'namespace alias';target.wrap='hard\ud800';if(target.wrap!=='hard\ud800'||target.getAttributeNS(null,'wrap')!=='hard\ud800'||target.getAttributeNS('urn:other','wrap')!=='hard')throw 'raw wrap backing';var copy=target.cloneNode(false);copy.wrap='soft';if(copy.wrap!=='soft'||target.wrap!=='hard\ud800'||copy.getAttributeNodeNS(null,'wrap')===target.getAttributeNodeNS(null,'wrap'))throw 'independent raw wrap copy';}"#);assert_eq!(body(&d,&f),"q=abcdefg");}
#[test]
fn textarea_wrap_fragment_dirty_copy_detach_reconnect_submit_independent_modes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var host=document.createElement('div');host.innerHTML='<textarea id=fresh name=fragment cols=2 wrap=hard>abcde</textarea>';document.getElementById('form').appendChild(host);var x=host.firstChild;x.value='ABCDE';var copy=x.cloneNode(true);copy.name='copy';copy.wrap='soft';host.appendChild(copy);x.parentNode.removeChild(x);x.wrap='HaRd';host.appendChild(x);if(copy.value!=='ABCDE'||copy.wrap!=='soft'||x.value!=='ABCDE'||x.wrap!=='HaRd')throw 'independent reconnected modes';"#);assert_eq!(body(&d,&f),"q=abc%0D%0Adef%0D%0Ag&copy=ABCDE&fragment=AB%0D%0ACD%0D%0AE");}
#[test]
fn textarea_wrap_resource_refusal_and_saved_child_origin_preserve_state_and_recover(){for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area');x.value='abcdefg';");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("textarea")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let capture=(p.state.retained,p.state.dom_commits,body(&d,&f));p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.textarea_wrap_set(object,&Value::String("soft".repeat(64))).is_err());assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,body(&d,&f)),capture);p.state.retained_limit=retained;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.wrap='soft';if(x.wrap!=='soft'||x.value!=='abcdefg')throw 'fresh wrap recovery';");assert_eq!(body(&d,&f),"q=abcdefg");}let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLTextAreaElement.prototype,'wrap'),calls=0;if(a.get.call(x)!=='hard')throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-textarea-wrap.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);p.begin_job();let error=p.runtime.execute("a.set.call(x,{toString:function(){calls++;return 'soft';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);p.set_location(&crate::navigation::address("https://textarea-wrap.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||x.wrap!=='hard')throw 'origin converted';a.set.call(x,'soft');");assert_eq!(body(&d,&f),"q=abcdefg");}
#[test]
fn textarea_wrap_encoded_get_limit_refuses_without_editor_mutation_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('area');x.cols=1;x.value='{}';","a".repeat(4096)));let before=format!("{:?}",d.nodes);assert_eq!(body(&d,&f).len(),28668);assert_eq!(format!("{:?}",d.nodes),before);let(mut d,mut f,mut p)=fixture_method("get");run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('area');x.cols=1;x.value='{}';","a".repeat(4096)));let owner=(0..d.nodes.len()).find(|n|d.attr(*n,"id")==Some("form")).unwrap();let l=crate::navigation::address("https://textarea-wrap.test/source",&crate::navigation::Location::home()).unwrap();let before=format!("{:?}",d.nodes);let error=f.submit_request(&d,owner,None,&l,&l).unwrap_err();assert!(error.contains("request limit"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();assert_eq!(f.controls[&n].value.text(),"a".repeat(4096));p.begin_job();run(&mut d,&mut f,&mut p,"x.value='ab';");let query=f.submit_request(&d,owner,None,&l,&l).unwrap().location.url.unwrap().query.unwrap();assert_eq!(query,"q=a%0D%0Ab");}
